export const MsgChat: RoomMessageKind = "chat";
export const MsgQuestion: RoomMessageKind = "question";
export const MsgUpvote: RoomMessageKind = "upvote";
export const MsgHand: RoomMessageKind = "hand";
export const MsgReaction: RoomMessageKind = "reaction";
