export const RecordingKeepMonths = 3;
/**
 *  Recording retention and storage.
 *  *
 *  * A recording is kept for the host's retention days (Admin -> Accounts, else the deployment's
 *  * RECORDINGS_RETENTION_DAYS, 30) from when it stopped. "Keep longer" adds RecordingKeepMonths
 *  * to the expiry in effect (AddMonths: the day clamps to the month's end) and can be repeated,
 *  * while the host's stored recordings are within their quota. The quota is the plan's
 *  * (plan_limits, migration 0148: no plan 2 GB, Professional and trials 10 GB, Business 50 GB,
 *  * Enterprise 200 GB) unless an admin set one for the account.
 */
export const RecordingQuotaWarnPercent = 90;
/**
 * MaxRecordingQuotaGB bounds an admin's per-account override.
 */
export const MaxRecordingQuotaGB = 10 * 1024;
/**
 * MaxRecordingRetentionDays bounds an admin's per-account default retention.
 */
export const MaxRecordingRetentionDays = 3650;
/**
 * RecordingStorage is GET /api/host/recording-storage: the meter and the rules behind it.
 */
export interface RecordingStorage {
  usedBytes: number /* int64 */;
  quotaBytes: number /* int64 */;
  /**
   * PlanQuotaBytes is the plan's number; QuotaOverride says an admin set QuotaBytes instead.
   */
  planQuotaBytes: number /* int64 */;
  quotaOverride?: boolean;
  plan?: Plan;
  /**
   * RetentionDays is how long a new recording is kept; 0 means this deployment keeps them.
   */
  retentionDays: number /* int */;
  keepMonths: number /* int */;
  /**
   * OverQuota is UsedBytes > QuotaBytes: "Keep longer" is refused until it is not.
   */
  overQuota?: boolean;
}
/**
 *  RecordingQuotaError is the 409 quota_exceeded body from "Keep longer": the usual error
 *  * shape plus the numbers the message is about.
 */
export interface RecordingQuotaError {
  error: string;
  message: string;
  usedBytes: number /* int64 */;
  quotaBytes: number /* int64 */;
}
/**
 * SetUserRecordingStorageRequest is PATCH /api/admin/users/{id}/recording-storage.
 * Replace semantics: null puts that one back on the plan / deployment default.
 */
export interface SetUserRecordingStorageRequest {
  recordingQuotaBytes?: number /* int64 */;
  recordingRetentionDays?: number /* int */;
}
/**
 *  KeepRecordingLinkRequest is POST /api/host/recordings/keep-link: the "Keep 3 more months"
 *  * link from an expiry email, signed for one recording, its host and the expiry the email was
 *  * about. A second press of the same link keeps nothing more.
 */
export interface KeepRecordingLinkRequest {
  recording: string;
  /**
   * Expires is the expiry the email was about, unix seconds.
   */
  expires: number /* int64 */;
  sig: string;
}
/**
 * KeepRecordingLinkResponse says what the link did and where the recording now stands.
 */
export interface KeepRecordingLinkResponse {
  /**
   * Status is "kept", or "already_kept" when this link was used before.
   */
  status: string;
  webinar: string;
  topic: string;
  expiresAt?: string;
}
/**
 * MaxVideoUploadBytes is the largest file one upload takes.
 */
export const MaxVideoUploadBytes: number /* int64 */ = 4 << 30;
/**
 * VideoUploadMinPartBytes is the smallest part size a file is cut into (S3 needs 5 MiB).
 */
export const VideoUploadMinPartBytes: number /* int64 */ = 8 << 20;
/**
 * VideoUploadMaxTitle bounds an uploaded video's title.
 */
export const VideoUploadMaxTitle = 200;
/**
 * StartVideoUploadRequest is POST /api/host/videos/uploads: the file about to be sent.
 */
export interface StartVideoUploadRequest {
  filename: string;
  sizeBytes: number /* int64 */;
  /**
   * Mime is the browser's File.type; the container is decided by the probe, not this.
   */
  mime: string;
  title?: string;
}
/**
 *  VideoUpload is one upload in flight: cut the file into PartCount parts of PartSize bytes
 *  * (the last one shorter), PUT each to a URL from .../parts, then .../complete. UploadedParts
 *  * is the parts the bucket already has, so an interrupted upload carries on where it stopped.
 */
export interface VideoUpload {
  id: string;
  filename: string;
  title: string;
  sizeBytes: number /* int64 */;
  partSize: number /* int64 */;
  partCount: number /* int */;
  uploadedParts: number /* int */[];
  createdAt: string;
}
/**
 * VideoUploadPartsRequest asks for upload URLs for these part numbers (1-based, at most 100).
 */
export interface VideoUploadPartsRequest {
  parts: number /* int */[];
}
/**
 * VideoUploadPartURL is where to PUT one part. Valid for an hour.
 */
export interface VideoUploadPartURL {
  part: number /* int */;
  url: string;
}
export interface VideoUploadPartsResponse {
  urls: VideoUploadPartURL[];
}
/**
 * CompleteVideoUploadRequest finishes an upload; Title, when set, replaces the one it started with.
 */
export interface CompleteVideoUploadRequest {
  title?: string;
}
/**
 * RenameVideoRequest is PATCH /api/host/videos/{id}.
 */
export interface RenameVideoRequest {
  title: string;
}
/**
 * RecordingPart is one start/stop take inside a session. The bytes are a
 * finished file; the session is the thing a host plays, shares and deletes.
 */
export interface RecordingPart {
  id: string;
  status: RecordingStatus;
  sizeBytes: number /* int64 */;
  durationMs: number /* int64 */;
  createdAt: string;
}
/**
 * StartRecordingRequest is sent by the browser that will do the capturing. It
 * names the container it can produce, because that differs by browser and the
 * server has to store what it is actually given.
 */
export interface StartRecordingRequest {
  mime: string;
}
/**
 * ShareRecordingRequest is sent by the host to configure public access and passcode.
 */
export interface ShareRecordingRequest {
  isPublic?: boolean;
  passcode?: string;
  /**
   * ShowCaptions is "Show captions on replays", for the session's recordings and simulives.
   */
  showCaptions?: boolean;
}
/**
 * PublicRecording is the sanitized recording metadata returned to anonymous viewers.
 */
export interface PublicRecording {
  id: string;
  webinar: string;
  topic: string;
  status: RecordingStatus;
  hostName: string;
  durationMs: number /* int64 */;
  sizeBytes: number /* int64 */;
  createdAt: string;
  ext: string;
  passcodeRequired: boolean;
  unlocked: boolean;
  uploadedToS3: boolean;
  uploadPercent: number /* int */;
  retentionDays: number /* int */;
  expiresAt?: string;
  parts?: RecordingPart[];
  /**
   *  Chapters are the AI recap's, once it has some and the recording is unlocked:
   * 	 * seconds from SessionStartedAt (when the session went live), which the player maps
   * 	 * onto the recording's parts by their createdAt.
   */
  chapters?: RecapChapter[];
  sessionStartedAt?: string;
  /**
   *  Captions says the session's own captions are served for this replay (captions.vtt
   * 	 * beside /stream): the host shows them on replays and there is a transcript. Only once
   * 	 * unlocked.
   */
  captions?: boolean;
}
/**
 * LiveParticipant is one row of the host's participant panel.
 * This comes from LiveKit's *server* API, not from the host's browser, which
 * matters: hidden attendees are excluded from client-side rosters by design, so
 * the host would otherwise be unable to moderate the people they have hidden.
 */
export interface LiveParticipant {
  identity: string;
  name: string;
  role: Role;
  joinedAt: string;
  publishing: string[];
  audioMuted: boolean;
  hidden: boolean;
  canPublish: boolean;
  /**
   * CanSpeak reports a microphone grant specifically, so the host's panel can
   * tell "allowed to speak" apart from "on the stage with a camera".
   */
  canSpeak: boolean;
  /**
   * AudioOnly is the scope the host granted, read back from what we minted —
   * not inferred from what they happen to be publishing. A full panelist with
   * their camera off is not the same as somebody allowed only to speak, and
   * guessing from the track list conflates the two.
   */
  audioOnly: boolean;
  /**
   * MutedByHost is the difference between "not a speaker" and "a speaker the
   * host silenced". Both have CanSpeak false, and the host's panel has to offer
   * "allow to speak again" for the second one rather than treating them as
   * audience.
   */
  mutedByHost: boolean;
  /**
   * CoHost is a panelist the host made their equal: full moderation rights,
   * not just a stage seat. See lk.Spec.CoHost.
   */
  coHost: boolean;
  /**
   *  Via is set for somebody the host can reach although the video server does not list
   * 	 * them, and says how they are connected without exposing the plumbing:
   * 	 *   "stream"  an edge viewer, watching the feed (their event stream and beats);
   * 	 *   "limited" an attendee whose video connection is down but whose browser is still
   * 	 *             talking to us (the presence poll), so chat and hands still work.
   * 	 * Empty for everyone the video server lists. Either kind can be invited to the stage.
   */
  via?: string;
}
/**
 * LiveScreenShare is what the one-share-at-a-time rule needs to know about a share.
 */
export interface LiveScreenShare {
  /**
   * StartedAtMicro is the SFU's publish stamp (TrackInfo.Version.UnixMicro): set once,
   * when the track's media first arrives, by the server's clock. Zero when unknown.
   */
  StartedAtMicro: number /* int64 */;
  /**
   * Muted is true once the share was muted, which is what the rule does to a loser.
   */
  Muted: boolean;
}
export interface LiveRoom {
  room: string;
  status: WebinarStatus;
  controls: SessionControls;
  participants: LiveParticipant[];
  attendees: number /* int */;
  onStage: number /* int */;
  /**
   *  Partial is true when the video server could not be read this time and Participants
   * 	 * holds only the people reached another way (Via set). The panel keeps its previous
   * 	 * video-server rows rather than showing an empty stage.
   */
  partial?: boolean;
}
/**
 * PresenceRequest is an attendee's browser saying it is still here while its video
 * connection is down (POST /api/webinars/{slug}/presence).
 */
export interface PresenceRequest {
  joinKey?: string;
}
/**
 *  PresenceResponse is what that attendee would otherwise have heard over the data channel: an
 *  * open stage invite (the offer the stage-invite packet carries), and whether the host has
 *  * already put them on the stage, in which case joining again returns a stage token.
 */
export interface PresenceResponse {
  invite?: PresenceInvite;
  onStage: boolean;
}
export interface PresenceInvite {
  audioOnly: boolean;
  recording: boolean;
}
export interface MutePatch {
  muted: boolean;
}
/**
 * StageRequest promotes an attendee onto the stage or sends them back.
 */
export interface StageRequest {
  role: Role; // panelist | attendee
  /**
   * AudioOnly is "allow to speak": the attendee gets a microphone and a screen
   * share, but no camera.
   * This is the common case by far. A host taking a question wants to hear one
   * person, not hand them the stage, and a full promotion means an unprepared
   * attendee's camera and desktop are one click from 500 people.
   */
  audioOnly: boolean;
}
export interface MuteAllResponse {
  muted: number /* int */;
}
/**
 * StageAllResponse reports a bulk allow-all-to-speak or revoke-all-speaking
 * action — how many attendees it actually applied to, the same shape as
 * MuteAllResponse and for the same reason: a host clicking a bulk action on
 * an empty or already-settled room needs to see that nothing silently
 * failed, not just a bare 200.
 */
export interface StageAllResponse {
  count: number /* int */;
}
/**
 * RegistrantPage is one page of the host's People tab.
 */
export interface RegistrantPage {
  items: RegistrantRow[];
  total: number /* int */;
  offset: number /* int */;
  approved: number /* int */;
  declined: number /* int */;
  pending: number /* int */;
  guests: number /* int */;
}
export interface RegistrantRow {
  id: string;
  name: string;
  email: string;
  company?: string;
  jobTitle?: string;
  phone?: string;
  state: RegistrationState;
  createdAt: string;
  hasAccount: boolean;
  /**
   *  IsGuest marks a row that came through the name-only door.
   * 	 *
   * 	 * Surfaced to the host because the alternative is an empty Email cell that reads as a
   * 	 * bug in the export. It is also the honest answer to "why can I not follow this person
   * 	 * up": nothing was collected, by design.
   */
  isGuest?: boolean;
  /**
   *  WhatsAppStatus is where this registrant stands on WhatsApp, in the CRM's own
   * 	 * words: one of the CRMStatus* consent values, or empty for somebody who is not in
   * 	 * the CRM at all.
   * 	 *
   * 	 * The same vocabulary the contacts list filters by, deliberately — see
   * 	 * CRMContactStatuses. One set of words means a host who filters the inbox to "opted
   * 	 * out" and reads the same phrase on this row is looking at one fact.
   * 	 *
   * 	 * A string rather than a bool because empty is NOT "no". A guest registration
   * 	 * collects neither a phone nor an email and so creates no contact at all, and
   * 	 * rendering that as "has not opted in" would invite the host to go and chase
   * 	 * somebody who was never asked and cannot be.
   * 	 *
   * 	 * Only filled in for a host who has connected WhatsApp; otherwise there is no CRM
   * 	 * to answer from and the columns are not shown.
   */
  whatsappStatus?: string;
  /**
   *  RFC3339 of the last message this person sent to the host's WhatsApp number, empty
   * 	 * when they never have — which is the ordinary case and reads as a dash.
   */
  lastInboundAt?: string;
  /**
   *  ZoomNote is why this person has no Zoom link, when the session runs on
   * 	 * Zoom. Empty otherwise. Never a join URL. A shared-link attendee has an
   * 	 * empty note and ZoomShared set.
   */
  zoomNote?: string;
  /**
   *  ZoomShared is true when this person uses the meeting's shared Zoom link
   * 	 * because Zoom would not register them. They still have a link. Never a
   * 	 * join URL, and not set when they have a personal registrant link.
   */
  zoomShared?: boolean;
  /**
   *  Joined is whether this registrant was in the room at all, and WatchMin how long
   * 	 * they watched once it was live — the session report's numbers, per registration
   * 	 * (store.AttachWatch). Zero and false before the webinar has run.
   */
  joined: boolean;
  watchMin: number /* int */;
  /**
   *  Tier is their engagement level from the webinar's latest score (engagement_scores),
   * 	 * empty until it has been computed or when they never joined.
   */
  tier?: EngagementTier;
  /**
   *  ContactID is this registrant's CRM contact, which is who a message is addressed to;
   * 	 * empty for a guest. LastMessage is the latest message either way on WhatsApp, for the
   * 	 * "Last message" column. Both filled in by the CRM, like WhatsAppStatus.
   */
  contactId?: string;
  lastMessage?: CRMMessage;
  /**
   *  Answers to the webinar's registration questions, keyed by CustomQuestion.ID. A
   * 	 * checkbox answer is "yes" when ticked; an unanswered question has no key.
   */
  answers?: { [key: string]: string};
}
export interface PanelistRequest {
  email: string;
}
/**
 * CoHostPatch turns a panelist into a second, equal moderator for this run of
 * the webinar, or turns them back into an ordinary panelist. See
 * lk.Spec.CoHost for exactly what that grants and withholds.
 */
export interface CoHostPatch {
  coHost: boolean;
}
/**
 * TransferHostRequest hands the webinar or meeting to a co-host already in the room.
 * Identity is their LiveKit identity: an invited panelist (user_<id>), or an attendee
 * on stage / meeting guest (att_<joinKey>) whose registration is linked to a confirmed
 * account, which becomes the owner. Only a co-host can take over (422 not_a_cohost
 * otherwise), and two racing hand-overs cannot both win (409 host_changed). The caller
 * remains an ordinary panelist so they can rejoin the stage later; the target is no
 * longer a co-host but the host. Publish grants are restored on handoff, so a muted
 * co-host (CanPublish false) is still a valid target.
 */
export interface TransferHostRequest {
  identity: string;
}
/**
 * AppConfig is public, unauthenticated, and read once by the frontend at boot.
 * It exists so the UI has no build-time constants for things an operator sets:
 * the product name, the public URL used to build share links, the attendee
 * ceiling shown next to the seat count.
 */
export interface AppConfig {
  appName: string;
  webBaseUrl: string;
  supportEmail?: string;
  maxAttendees: number /* int */;
  signupOpen: boolean;
  /**
   * DefaultMaxMeetingMin is the system default maximum meeting duration in minutes (default 180 = 3h).
   */
  defaultMaxMeetingMin: number /* int */;
  /**
   * CaptionLanguages is the captions language list for the scheduling form and the room;
   * DefaultCaptionsLanguage is what a new webinar starts with (CAPTIONS_DEFAULT_LANGUAGE).
   */
  captionLanguages: CaptionLanguage[];
  defaultCaptionsLanguage: string;
  /**
   *  BoxRegions is the areas of the video server pool a session can be placed in (e.g. "in",
   * 	 * "us"), the default first. The schedule form offers the choice only when there are two or
   * 	 * more; empty when the on-demand video server is off.
   */
  boxRegions: string[];
  /**
   * GoogleClientID and GoogleAPIKey turn on the Google Drive source in the
   * share-a-file picker. Both are public values — see config.Config — and both
   * are empty unless an operator sets them, which the picker reports as "not
   * configured" rather than failing on click.
   */
  googleClientId?: string;
  googleApiKey?: string;
  /**
   *  YouTubeOAuth is whether GOOGLE_CLIENT_ID and GOOGLE_CLIENT_SECRET are both
   * 	 * set, so Account settings can offer Connect YouTube. The same pair turns on
   * 	 * GoogleAuth (Continue with Google). GoogleClientID is also Drive Picker.
   */
  youtubeOAuth?: boolean;
  /**
   *  WhatsAppConnect is whether META_APP_ID, META_APP_SECRET and
   * 	 * META_WHATSAPP_CONFIG_ID are all set, so Account settings can offer Connect
   * 	 * WhatsApp. Only the flag is public: the app id and the signup configuration id
   * 	 * are handed out by GET /api/host/whatsapp/connect, to a signed-in host at the
   * 	 * moment they click, rather than to every anonymous visitor at boot.
   */
  whatsappConnect?: boolean;
  /**
   *  GoogleAuth is Continue with Google via first-party OAuth on this origin.
   * 	 * Public values only — the client secret stays on the API. When false the
   * 	 * Continue with Google button is hidden.
   * 	 *
   * 	 * supabaseUrl / supabaseAnonKey remain for an unused legacy exchange path.
   */
  supabaseUrl?: string;
  supabaseAnonKey?: string;
  googleAuth?: boolean;
  /**
   *  CloudRecordingEnabled is whether this instance has object storage for
   * 	 * recordings at all (RECORDINGS_ENABLED). Separate from JoinResponse.CanRecord,
   * 	 * which is about the ACCOUNT (host or panelist); this is about the INSTANCE.
   * 	 * The record control uses it to decide whether to offer "the cloud" as a
   * 	 * destination at all, rather than offering a button that always 503s — local,
   * 	 * on-device recording (see web/lib/local-recording.ts) needs neither this nor
   * 	 * the server's storage, so it is unaffected by it either way.
   */
  cloudRecordingEnabled: boolean;
  recordingMode?: string;
  /**
   *  VideoUploadEnabled is whether a host can upload a video for a Simulive: the
   * 	 * recordings store is object storage the browser can upload to directly.
   */
  videoUploadEnabled?: boolean;
  /**
   * RecordingsRetentionDays is how long cloud recordings are kept before
   * automatic deletion. 0 means they are kept until a host deletes them.
   */
  recordingsRetentionDays: number /* int */;
  /**
   * EmailConfigured is whether SMTP can actually deliver. The UI uses it to
   * say "we'll email you" vs "save this join link; mail is off".
   */
  emailConfigured: boolean;
  /**
   * TelemetryEnabled mirrors config.Config.TelemetryEnabled: whether POST
   * /telemetry accepts anything. The frontend's telemetry poller checks this
   * before attaching a single listener or sampling a single stat, so turning
   * the flag off also turns off the client-side work, not just the endpoint.
   */
  telemetryEnabled?: boolean;
  /**
   * AV1Publish is the AV1 kill switch (config.Config.AV1Publish, env AV1_PUBLISH):
   * "off", "meetings" or "on". The room reads it before its first publish
   * (web/lib/codec-policy.ts av1RoomVerdict); anything else, or missing, means off.
   */
  av1Publish: string;
  /**
   *  FeatureCatalogue is every per-account switch this server has, with the sentence
   * 	 * that explains each one — see Features. Sent here rather than with the accounts
   * 	 * list so that adding a switch does not change the shape of that response, and so
   * 	 * the admin screen renders what this build actually supports instead of a list the
   * 	 * browser keeps its own copy of.
   */
  featureCatalogue: Feature[];
  /**
   * FeatureGroups are the headings the catalogue is filed under (Feature.Group), in order.
   */
  featureGroups: FeatureGroup[];
  /**
   *  DownloadsVisible is the admin's site-wide switch for /download (SiteSettings): when
   * 	 * false the page answers with a redirect home for everyone but admins, and the web drops
   * 	 * every link to it. False by default.
   */
  downloadsVisible: boolean;
}
/**
 *  TelemetryEvent is one entry in a POST /telemetry batch — the shape is
 *  * intentionally loose (Payload is a bag of whatever the client measured)
 *  * because this is a temporary diagnostic path for one test window, not a
 *  * contract anything else in the app depends on. See handleTelemetry.
 */
export interface TelemetryEvent {
  event: string;
  timestamp: number /* int64 */; // epoch ms, client clock
  payload?: { [key: string]: any};
}
export interface APIError {
  error: string;
  message: string;
  fields?: { [key: string]: string};
}
export interface StatusResponse {
  status: string;
}
