/**
 *  Integration cards on Settings. One shape for every provider, so the page
 *  * renders the list and does not grow a branch when another app is added.
 *  *
 *  * Status is connected, off, or soon. Category is messaging, streaming, or soon
 *  * (the compact "coming soon" rows). Credentials stay in their existing columns;
 *  * this type is only what the browser is allowed to see.
 */
export const IntegrationActionInfo = "info";
/**
 *  Integration cards on Settings. One shape for every provider, so the page
 *  * renders the list and does not grow a branch when another app is added.
 *  *
 *  * Status is connected, off, or soon. Category is messaging, streaming, or soon
 *  * (the compact "coming soon" rows). Credentials stay in their existing columns;
 *  * this type is only what the browser is allowed to see.
 */
export const IntegrationActionSignup = "signup";
/**
 * IntegrationActionStreamKey opens a form for a Stream URL and key, sent
 * to Href with Method as SaveStreamKeyRequest. LinkedIn, Instagram and
 * Facebook Live use it.
 */
export const IntegrationActionStreamKey = "stream_key";
/**
 * SaveStreamKeyRequest is a Stream URL and key pasted on an integration card.
 */
export interface SaveStreamKeyRequest {
  streamUrl: string;
  streamKey: string;
}
/**
 *  WebinarStreamDestination is one RTMP platform (LinkedIn, Instagram,
 *  * Facebook) as one room sees it.
 *  *
 *  * Configured: the host saved a stream key. Paused: the host paused it in this
 *  * room. Streaming: the webinar is live, configured and not paused, so the mix
 *  * is being pushed there. Hint names the destination without the key.
 */
export interface WebinarStreamDestination {
  platform: string;
  configured: boolean;
  paused: boolean;
  streaming: boolean;
  hint?: string;
  /**
   * Refused is true when the platform refused this key during the session. The
   * webinar's own stream carries on; this destination is skipped until the host
   * saves a new key or resumes it.
   */
  refused?: boolean;
}
/**
 * SetWebinarStreamPausedRequest pauses or resumes one platform for one webinar.
 */
export interface SetWebinarStreamPausedRequest {
  paused: boolean;
}
export interface IntegrationStep {
  title: string;
  body: string;
}
export interface IntegrationAction {
  id: string;
  label: string;
  href?: string;
  method?: string;
  kind: string;
  detail?: string;
  confirm?: string;
  menu?: boolean;
  steps?: IntegrationStep[];
}
export interface IntegrationCard {
  id: string;
  name: string;
  tagline: string;
  category: string;
  status: string;
  detail: string;
  who?: string;
  whoNote?: string;
  warn?: string;
  mark: string;
  text?: string;
  tone: string;
  actions?: IntegrationAction[];
  interested?: boolean;
}
export interface IntegrationsResponse {
  integrations: IntegrationCard[];
}
/**
 *  ReplayPoll is a poll or quiz on a simulive's replay timeline: the question and options
 *  * only. It is not what the audience votes in — at its moment the server opens a real poll in
 *  * the simulive (polls.replay_key), which the room reads through its Polls panel like any
 *  * other — so the timeline never carries a tally, the original's or anyone's. Correct is the
 *  * host preview's only.
 */
export interface ReplayPoll {
  question: string;
  options: string[];
  quiz?: boolean;
  correct?: number /* int */;
}
/**
 * ReplayReaction is one emoji of a replayed reaction burst and how many were sent.
 */
export interface ReplayReaction {
  emoji: string;
  count: number /* int */;
}
/**
 *  ReplayItem is one moment of a simulive's engagement replay.
 *  *
 *  * ID is this item's position in this timeline ("r1", "r2", …) — never a source id. Ref, on an
 *  * answer or a poll's close, is the ID of the question or poll it belongs to. Name is already
 *  * privacy-shortened ("Priya S."); there is no identity, email or join key anywhere in it.
 *  *
 *  * Kinds: chat, question, answer; poll (the original opened it here — the room re-reads its
 *  * polls) and poll_close (it closed here; a quiz's answer is revealed); reaction (a burst of
 *  * the original audience's emoji, counts per emoji, nobody's name).
 *  *
 *  * Key and Hidden are the host preview's only (GET /api/host/webinars/{slug}/replay): the
 *  * source row an item came from, for PUT .../replay/hidden, and whether the host hid it.
 */
export interface ReplayItem {
  id: string;
  kind: string; // chat | question | answer | poll | poll_close | reaction
  atMs: number /* int64 */;
  name?: string;
  role?: Role;
  text?: string;
  anonymous?: boolean;
  ref?: string;
  poll?: ReplayPoll;
  reactions?: ReplayReaction[];
  key?: string;
  hidden?: boolean;
}
/**
 *  ReplayTimeline is the whole replay, sorted by AtMs. The client schedules it against the
 *  * video's own playback position: everything at or before the position at once (a late
 *  * joiner's catch-up), the rest as the video reaches it. Enabled false (with no items) is a
 *  * session without the replay: not a simulive, the switch off, or no recording.
 */
export interface ReplayTimeline {
  enabled: boolean;
  /**
   * The recording's length, 0 when unknown.
   */
  durationMs: number /* int64 */;
  items: ReplayItem[];
}
/**
 * Replay filters (GET /api/host/webinars/{slug}/replay?filter=).
 */
export const ReplayFilterAll = "all";
/**
 * Replay filters (GET /api/host/webinars/{slug}/replay?filter=).
 */
export const ReplayFilterChat = "chat";
/**
 * Replay filters (GET /api/host/webinars/{slug}/replay?filter=).
 */
export const ReplayFilterQA = "qa";
/**
 * Replay filters (GET /api/host/webinars/{slug}/replay?filter=).
 */
export const ReplayFilterPolls = "polls";
/**
 * Replay filters (GET /api/host/webinars/{slug}/replay?filter=).
 */
export const ReplayFilterReactions = "reactions";
/**
 * ReplayCounts is how many items each filter holds, and how many of all are hidden.
 */
export interface ReplayCounts {
  all: number /* int */;
  chat: number /* int */;
  qa: number /* int */;
  polls: number /* int */;
  reactions: number /* int */;
  hidden: number /* int */;
}
/**
 *  ReplayPage is one page of the host's preview: GET /api/host/webinars/{slug}/replay with
 *  * filter (all | chat | qa | polls | reactions), q (search), at (jump: the page starting at
 *  * the first item at or after this offset, ms), cursor and limit (default 50, at most 200).
 *  * Total is the number of items matching the filter and search; Offset is where Items start
 *  * among them. NextCursor / PrevCursor are empty at either end.
 */
export interface ReplayPage {
  enabled: boolean;
  durationMs: number /* int64 */;
  items: ReplayItem[];
  total: number /* int */;
  offset: number /* int */;
  nextCursor?: string;
  prevCursor?: string;
  counts: ReplayCounts;
}
/**
 *  ReplayHideRequest hides items of a simulive's replay, or shows them again: one Key, a
 *  * list of Keys (a page), or — with All — every item matching Filter and Q.
 */
export interface ReplayHideRequest {
  key?: string;
  keys?: string[];
  all?: boolean;
  filter?: string;
  q?: string;
  hidden: boolean;
}
/**
 * ReplayHideResponse is what a hide or show changed, and the counts after it.
 */
export interface ReplayHideResponse {
  changed: number /* int */;
  counts: ReplayCounts;
}
